function buildOperation(definition) {
  const [, , tag, summary, operationId, requestSchema, responseSchema, successStatus = '200', securityKind = 'bearer', parameterNames = []] = definition
  const isCsv = responseSchema === 'CsvDocument'
  const isHtml = responseSchema === 'HtmlDocument'
  const isBinary = responseSchema === 'BinaryDocument'
  const response = successStatus === '204'
    ? { description: 'The operation completed successfully with no response body.' }
    : {
        description: 'Successful response.',
        content: isCsv
          ? { 'text/csv': { schema: { type: 'string' } } }
          : isHtml
            ? { 'text/html': { schema: { type: 'string' } } }
            : isBinary
              ? { 'application/octet-stream': { schema: { type: 'string', format: 'binary' } } }
              : { 'application/json': { schema: ref(responseSchema || 'GenericObject') } },
      }
  const operationParameters = [
    ...parameterNames.map(paramRef),
    ...(idempotentOperations.has(operationId) ? [paramRef('IdempotencyKey')] : []),
  ]
  return {
    tags: [tag],
    summary,
    operationId,
    security: securityKind === 'public' ? [] : securityKind === 'cookie' ? [{ refreshCookie: [] }] : [{ bearerAuth: [] }],
    ...(operationParameters.length ? { parameters: operationParameters } : {}),
    ...(requestSchema ? {
      requestBody: {
        required: true,
        content: requestSchema === 'FileUploadRequest'
          ? { 'multipart/form-data': { schema: ref(requestSchema) } }
          : requestSchema === 'CsvDocument'
            ? { 'text/csv': { schema: ref(requestSchema) } }
            : { 'application/json': { schema: ref(requestSchema) } },
      },
    } : {}),
    responses: { [successStatus]: response, ...errors },
  }
}

function buildPaths(definitions) {
  return definitions.reduce((paths, definition) => {
    const [method, path] = definition
    paths[path] ||= {}
    paths[path][method] = buildOperation(definition)
    return paths
  }, {})
}

